import moment from 'moment-timezone'

export const tieringToTieringData = (obj = {}) => {
  const {
    with_hard_copy: whc,
    with_hard_copy_keys: whcKeys,
    with_hard_copy_type: whcType,

    without_hard_copy: wohc,
    without_hard_copy_keys: wohcKeys,
    without_hard_copy_type: wohcType
  } = obj

  let newWhc = {}
  if (whcType === 'tiering') {
    const { premium_type: premiumType } = whc
    newWhc = {
      [premiumType]: [
        ...whcKeys?.map(k => whc.tiering[k])
      ]
    }
  } else {
    newWhc = {
      flat: whc?.flat
    }
  }
  let newWohc = {}
  if (wohcType === 'tiering') {
    const { premium_type: premiumType } = wohc
    newWohc = {
      [premiumType]: [
        ...wohcKeys.map(k => wohc.tiering[k])
      ]
    }
  } else {
    newWohc = {
      flat: wohc.flat
    }
  }
  return {
    with_hard_copy: newWhc,
    without_hard_copy: newWohc
  }
}

export const formToFormData = (formValues, providerCode, editPresetId, isEdit) => {
  const {
    stamp_duty: stampDuty,
    admin_fee: adminFee,
    preset_type: presetType,
    closing_slip_sla: css,
    quotation_slip_sla: qss,
    preset_start_date: startDate,
    preset_end_date: endDate,
    package: pkg,
    ...newFormValues
  } = formValues

  const newStampDuty = tieringToTieringData(stampDuty)
  const newAdminFee = tieringToTieringData(adminFee)
  newFormValues.stamp_duty = newStampDuty
  newFormValues.admin_fee = newAdminFee
  newFormValues.preset_type = presetType
  newFormValues.preset_start_date = startDate.format('YYYY-MM-DD')
  newFormValues.preset_end_date = endDate.format('YYYY-MM-DD')
  newFormValues.package = pkg || null
  if (presetType === 'offline') {
    newFormValues.closing_slip_sla = css
    newFormValues.quotation_slip_sla = qss
  }
  return newFormValues
}

export const tieringDataToTiering = (tieringData, tieringType, isView = false) => {
  const {
    with_hard_copy: whc,
    without_hard_copy: wohc,
    ...newTieringData
  } = tieringData
  let premiumType = Object.keys(whc)[0]
  const tierings = {}
  if (premiumType === 'flat') {
    newTieringData.with_hard_copy_type = 'flat'
    newTieringData.with_hard_copy = whc
  } else {
    newTieringData.with_hard_copy_type = 'tiering'
    const tieringKeys = []
    const newTiering = {}
    const tiering = whc[premiumType]
    tiering.forEach((t, i) => {
      tieringKeys.push(`${tieringType}_with_hard_copy_${i}`)
      newTiering[`${tieringType}_with_hard_copy_${i}`] = t
    })
    if (isView) {
      newTieringData.with_hard_copy = {
        premium_type: premiumType,
        tiering: newTiering
      }
    } else {
      newTieringData.with_hard_copy = {
        premium_type: premiumType
      }
    }
    newTieringData.with_hard_copy_keys = tieringKeys
    tierings.with_hard_copy = newTiering
  }
  premiumType = Object.keys(wohc)[0]
  if (premiumType === 'flat') {
    newTieringData.without_hard_copy_type = 'flat'
    newTieringData.without_hard_copy = wohc
  } else {
    newTieringData.without_hard_copy_type = 'tiering'
    const tieringKeys = []
    const newTiering = {}
    const tiering = wohc[premiumType]
    tiering.forEach((t, i) => {
      tieringKeys.push(`${tieringType}_without_hard_copy_${i}`)
      newTiering[`${tieringType}_without_hard_copy_${i}`] = t
    })
    if (isView) {
      newTieringData.without_hard_copy = {
        premium_type: premiumType,
        tiering: newTiering
      }
    } else {
      newTieringData.without_hard_copy = {
        premium_type: premiumType
      }
    }
    newTieringData.without_hard_copy_keys = tieringKeys
    tierings.without_hard_copy = newTiering
  }
  return [newTieringData, tierings]
}

export const formDataToView = (formData) => {
  const {
    stamp_duty: stampDuty,
    admin_fee: adminFee,
    provider,
    product,
    package: pkg,
    ...formVals
  } = formData
  const [newStampDuty] = tieringDataToTiering(stampDuty, 'stamp_duty', true)
  const [newAdminFee] = tieringDataToTiering(adminFee, 'admin_fee', true)
  return {
    formData: {
      ...formVals,
      stamp_duty: newStampDuty,
      admin_fee: newAdminFee,
      provider: provider.code,
      product: product.code,
      package: pkg.code
    },
    selectData: {
      provider: provider.name,
      product: product.name,
      package: pkg.name
    }
  }
}

export const formDataToEdit = (formData) => {
  const {
    stamp_duty: stampDuty,
    admin_fee: adminFee,
    created_at: ca,
    created_by: cb,
    deleted_at: da,
    deleted_by: db,
    updated_at: ua,
    updated_by: ub,
    version,
    preset_uuid: pu,
    preset_start_date: psd,
    preset_end_date: ped,
    ...formVals
  } = formData
  const [newStampDuty, tieringSD] = tieringDataToTiering(stampDuty, 'stamp_duty')
  const [newAdminFee, tieringAF] = tieringDataToTiering(adminFee, 'admin_fee')
  return [{
    ...formVals,
    stamp_duty: newStampDuty,
    admin_fee: newAdminFee,
    preset_start_date: moment(psd),
    preset_end_date: moment(ped)
  }, {
    stamp_duty: tieringSD,
    admin_fee: tieringAF
  }]
}

