import get from 'lodash/get'
import moment from 'moment-timezone'
import { capitalizeFirstLetter } from '../../helpers/converters'
import { ViewPresetStyle } from './index.style'
import PropTypes from 'prop-types'

const ViewPreset = (props) => {
  const { presetData, selectData } = props
  const renderItem = (item) => {
    switch (item.type) {
      case 'text-rendered':
        return (<div className='preset-text'>{item.rendered}</div>)
      case 'text':
        return (<div className='preset-text'>{get(presetData, item.key, '')}</div>)
      case 'percent':
        return (<div className='preset-text percent'>{get(presetData, item.key, '')}%</div>)
      case 'radio':
        return (<div className='preset-text'>{get(presetData, item.key, '') === true ? item.true : item.false}</div>)
      default:
        return null
    }
  }
  const renderItemWithLabel = (component, label, className) => {
    return (
      <div className='preset-field' key={label}>
        <div className='preset-label'>{label}</div>
        <div className={`preset-component ${className || ''}`}>{component}</div>
      </div>
    )
  }
  const renderFormItemList = (itemList) => {
    return itemList?.map(item => {
      const [rendered, title, className = ''] = item
      return renderItemWithLabel(
        renderItem(rendered),
        title,
        className
      )
    })
  }
  const renderTieringList = (keys = [], data = {}) => {
    return (
      <>
        <div className='preset-tiering'>
          {get(data, 'premium_type')?.split('_')?.map(capitalizeFirstLetter)?.join(' ')}
        </div>
        <div className='preset-tiering'>
          <table>
            <thead>
              <tr>
                <th>From</th>
                <th>To</th>
                <th>Amount</th>
              </tr>
            </thead>
            <tbody>
              {
                keys.map(k => (
                  <tr key={k}>
                    <td className='rupiah'>{get(data, `tiering.${k}.min`)}</td>
                    <td className='rupiah'>{get(data, `tiering.${k}.max`)}</td>
                    <td className='rupiah'>{get(data, `tiering.${k}.fee`)}</td>
                  </tr>
                ))
              }
            </tbody>
          </table>
        </div>
      </>
    )
  }
  const renderTiering = (data) => {
    if (!data) return null
    const {
      with_hard_copy: whc,
      with_hard_copy_type: whcType,
      with_hard_copy_keys: whcKeys,
      without_hard_copy: wohc,
      without_hard_copy_type: wohcType,
      without_hard_copy_keys: wohcKeys
    } = data
    return (
      <>
        {
          whcType === 'flat'
            ? (
              <div className='preset-text'>
                with hardcopy <span className='whc rupiah'>{get(whc, 'flat')}</span>
              </div>
              )
            : (
              <>
                <div className='preset-text'>with hardcopy</div>
                {renderTieringList(whcKeys, whc)}
              </>
              )
        }
        {
          wohcType === 'flat'
            ? (
              <div className='preset-text'>
                without hardcopy <span className='wohc rupiah'>{get(wohc, 'flat')}</span>
              </div>
              )
            : (
              <>
                <div className='preset-text'>without hardcopy</div>
                {renderTieringList(wohcKeys, wohc)}
              </>
              )
        }
      </>
    )
  }
  return (
    <ViewPresetStyle>
      {
        renderFormItemList([
          [
            {
              type: 'text',
              key: 'name'
            },
            'Preset Name'
          ],
          [
            {
              type: 'text-rendered',
              key: 'preset_type',
              rendered: `${capitalizeFirstLetter(get(presetData, 'preset_type', ''))} Policy`
            },
            'Type'
          ],
          [
            {
              type: 'text-rendered',
              key: 'provider',
              rendered: get(selectData, 'provider', '') || get(presetData, 'provider', '')
            },
            'Provider Name'
          ],
          [
            {
              type: 'text-rendered',
              key: 'product',
              rendered: get(selectData, 'product', '') || get(presetData, 'product', '')
            },
            'Product Type'
          ],
          [
            {
              type: 'text-rendered',
              key: 'package',
              rendered: get(selectData, 'package', '') || get(presetData, 'package', '')
            },
            'Package Name'
          ],
          [
            {
              type: 'radio',
              key: 'include_brokerage_vat',
              true: 'Include',
              false: 'Exclude'
            },
            'BF VAT'
          ],
          [
            {
              type: 'radio',
              key: 'include_brokerage_wht',
              true: 'Include',
              false: 'Exclude'
            },
            'BF WHT'
          ],
          [
            {
              type: 'percent',
              key: 'agent_bf_commission_percent'
            },
            'Agent Commission % From BF'
          ],
          [
            {
              type: 'percent',
              key: 'pasarpolis_bf_commission_percent'
            },
            'PasarPolis Fee % From BF'
          ],
          [
            {
              type: 'percent',
              key: 'discount_percent'
            },
            'Max Discount To Client'
          ],
          [
            {
              type: 'radio',
              key: 'show_discount_on_policy',
              true: 'Yes',
              false: 'No'
            },
            'Discount Appear on Policy'
          ],
          [
            {
              type: 'radio',
              key: 'include_ef_vat',
              true: 'Exclude',
              false: 'No'
            },
            'EF VAT'
          ],
          [
            {
              type: 'radio',
              key: 'include_ef_wht',
              true: 'Include',
              false: 'Exclude'
            },
            'EF WHT'
          ],
          [
            {
              type: 'percent',
              key: 'agent_ef_commission_percent'
            },
            'Agent Extra Commission % From EF'
          ],
          [
            {
              type: 'percent',
              key: 'pasarpolis_ef_commission_percent'
            },
            'PasarPolis Fee % From EF'
          ]
        ])
      }
      {
        renderItemWithLabel(
          renderTiering(get(presetData, 'admin_fee')),
          'Admin Fee'
        )
      }
      {
        renderItemWithLabel(
          <div className='preset-text'>
            {
              get(presetData, 'hard_copy_required', '') === true
                ? 'Required'
                : 'Not Required'
            }
          </div>,
          'Hardcopy Status'
        )
      }
      {
        renderItemWithLabel(
          renderTiering(get(presetData, 'stamp_duty')),
          'Stamp Duty'
        )
      }
      {
        renderItemWithLabel(
          <div className='preset-text'>{get(presetData, 'activate_policy_sla', '')} days</div>,
          'SLA To Activate Policy'
        )
      }
      {get(presetData, 'preset_type', '') === 'offline' &&
        <>
          {renderItemWithLabel(
            <div className='preset-text'>{get(presetData, 'quotation_slip_sla', '')} days</div>,
            'SLA Of Quotation Slip'
          )}
          {
            renderItemWithLabel(
              <div className='preset-text'>{get(presetData, 'closing_slip_sla', '')} days</div>,
              'SLA To Closing Slip'
            )
          }
        </>}
      {
        renderItemWithLabel(
          <div className='preset-text'>{get(presetData, 'allow_paylater', '') === true ? 'Available' : 'Not Available'}</div>,
          'Pay Later'
        )
      }
      {
        renderItemWithLabel(
          <div className='date-text'>
            <span className='date from'>From</span> {moment(get(presetData, 'preset_start_date')).format('DD-MM-YYYY')}
            <span className='date'>To</span> {moment(get(presetData, 'preset_end_date')).format('DD-MM-YYYY')}
          </div>,
          'Effective Date'
        )
      }
    </ViewPresetStyle>
  )
}

ViewPreset.propTypes = {
  presetData: PropTypes.object,
  selectData: PropTypes.object
}

export default ViewPreset
