import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

export const PresetContext = createContext()

export const PresetContextProvider = ({ children }) => {
  return (
    <PresetContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {children}
    </PresetContext.Provider>
  )
}

export const usePresetContextValue = () => useContext(PresetContext)
